// Fisher-Yates shuffle
export function shuffleArray(arr) {
  const copy = [...arr];
  for (let i = copy.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [copy[i], copy[j]] = [copy[j], copy[i]];
  }
  return copy;
}

// Build structured vocabulary objects with fresh randomized options every time
export function getExpandedVocabForLevel(levelId) {
  const rawList = RAW_VOCAB_BANK[levelId] || RAW_VOCAB_BANK.A1;
  const allWordsInLevel = rawList.map((entry) => entry[0]);

  const structured = rawList.map((entry, idx) => {
    const [word, phonetic, type, tr, synonym, example, exampleTr] = entry;
    const otherWords = allWordsInLevel.filter((w) => w.toLowerCase() !== word.toLowerCase());
    const distractors = shuffleArray(otherWords).slice(0, 3);
    const clozeOptions = shuffleArray([word, ...distractors]);

    return {
      id: `${levelId.toLowerCase()}-vw-${idx + 1}`,
      word,
      phonetic,
      type,
      tr,
      synonym,
      example,
      exampleTr,
      clozeOptions
    };
  });

  return shuffleArray(structured);
}
